inputs = ['ja', 'fybk', 'gac', 'guy', 'gz']
outputs = ['jdfyi', 'khdkdk', 'gdfyic', 'guh', 'gz']

print("Detailed analysis:")
for i in range(len(inputs)):
    inp, outp = inputs[i], outputs[i]
    print(f"\n{inp} -> {outp}")

    # Let's look at character by character
    if inp != outp:
        print("  Position by position:")
        min_len = min(len(inp), len(outp))
        for j in range(min_len):
            if inp[j] != outp[j]:
                print(f"    Position {j}: '{inp[j]}' -> '{outp[j]}'")

        if len(inp) < len(outp):
            print(f"  Extra chars in output: {outp[len(inp):]}")
        elif len(inp) > len(outp):
            print(f"  Missing chars in output: {inp[len(outp):]}")

